CREATE TABLE leave_applications (id text PRIMARY KEY, school_id text NOT NULL REFERENCES tenants(id), student_id text NOT NULL REFERENCES students(id), submitted_by text NOT NULL REFERENCES users(id), reason text NOT NULL, starts_on date NOT NULL, ends_on date NOT NULL, status text NOT NULL CHECK(status IN ('pending','approved','rejected')), approved_by text REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), decided_at timestamptz, CHECK(starts_on <= ends_on));
